#[capability(
    module = "ups",
    id = "label-recovery",
    display_name = r##"Label Recovery"##,
    description = r##"The Label Shipping API allows us to retrieve forward and return labels."##,
    side_effects = true
)]
pub async fn label_recovery(
    input: LabelRecoveryInput,
) -> Result<LabelrecoveryResponseWrapper, AgentError> {
    let connection = kit::require_connection(&input._connection, "UPS")?;
    input.request()?.send(connection, "UPS").await
}

impl LabelRecoveryInput {
    /// The request this capability sends; the connection supplies host and credentials.
    pub fn request(&self) -> Result<kit::Request, AgentError> {
        let path = String::from("/api/labels/v1/recovery");
        let request = kit::Request::new("POST", path);
        request.json_body(
            kit::Body::new()
                .field_opt("LabelDelivery", &self.label_delivery)
                .field_opt("LabelSpecification", &self.label_specification)
                .field_opt("Locale", &self.locale)
                .field_opt(
                    "MailInnovationsTrackingNumber",
                    &self.mail_innovations_tracking_number,
                )
                .field_opt("ReferenceValues", &self.reference_values)
                .field("Request", &self.request)
                .field_opt("TrackingNumber", &self.tracking_number)
                .field_opt("TrackingNumbers", &self.tracking_numbers)
                .field_opt("Translate", &self.translate)
                .field_opt("UPSPremiumCareForm", &self.ups_premium_care_form)
                .envelope("LabelRecoveryRequest"),
            "UPS",
        )
    }
}

